import { useEffect, useMemo, useState } from 'react'
import { CalendarDays, Recycle, Users, Weight } from 'lucide-react'
import { getResidents, getSummary, getWasteEvents } from '../../api/rwa'
import CategoryBarChart from '../../components/CategoryBarChart'
import CategoryPieChart from '../../components/CategoryPieChart'
import StatCard from '../../components/StatCard'
import WasteFeedTable from '../../components/WasteFeedTable'

const daysAgo = (days) => new Date(Date.now() - days * 86400000).toISOString().slice(0, 10)
export default function RwaDashboard() {
  const [summary, setSummary] = useState(null); const [residents, setResidents] = useState([]); const [events, setEvents] = useState([]); const [filters, setFilters] = useState({ category: '', from_timestamp: '', to_timestamp: '' })
  const load = () => Promise.all([getSummary(), getResidents(), getWasteEvents(Object.fromEntries(Object.entries(filters).filter(([,v]) => v)))]).then(([s,r,e]) => {setSummary(s);setResidents(r);setEvents(e)}).catch(console.error)
  useEffect(() => { load() }, [])
  const lastWeek = useMemo(() => Array.from({length:7}, (_, index) => { const day = daysAgo(6-index); const totals = { label: day.slice(5), PLASTIC:0, ORGANIC:0, METAL:0, OTHER:0 }; events.filter((item) => item.timestamp?.slice(0,10) === day).forEach((item) => totals[item.category]++); return totals }), [events])
  const leaderboard = [...residents].sort((a,b) => b.earned_points - a.earned_points).slice(0, 8)
  const todayCount = Object.values(summary?.today_by_category || {}).reduce((a,b)=>a+b,0); const weekCount = Object.values(summary?.week_by_category || {}).reduce((a,b)=>a+b,0)
  return <div className="space-y-7"><div><p className="text-sm text-moss">Residential welfare association</p><h1 className="text-4xl text-forest">Society waste desk</h1></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={Recycle} label="Today processed" value={todayCount} trend="classified items"/><StatCard icon={CalendarDays} label="Past 7 days" value={weekCount} tone="moss"/><StatCard icon={Users} label="Active residents" value={summary?.active_residents_today ?? 0} trend={`of ${summary?.total_residents ?? 0} total`} tone="terracotta"/><StatCard icon={Weight} label="Categories tracked" value={Object.keys(summary?.by_category || {}).length} tone="other"/></div><div className="grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><section className="panel p-6"><h2 className="section-title">Seven-day category volume</h2><div className="mt-5"><CategoryBarChart data={lastWeek}/></div></section><section className="panel p-6"><h2 className="section-title">All-time sorting mix</h2><CategoryPieChart data={summary?.by_category || {}}/></section></div><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><section className="panel p-6"><h2 className="section-title">Resident leaderboard</h2><div className="mt-4 overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-line"><th className="table-head py-3">Resident</th><th className="table-head py-3">Items</th><th className="table-head py-3">Points</th></tr></thead><tbody>{leaderboard.map((resident, index) => <tr key={resident.id} className="border-b border-line/70"><td className="py-3"><span className="mr-2 text-terracotta">{index+1}.</span>{resident.name}</td><td>{resident.event_count}</td><td className="font-semibold">{resident.earned_points}</td></tr>)}</tbody></table></div></section><section className="panel p-6"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="section-title">Waste event log</h2><p className="mt-1 text-sm text-moss">Filter by category and classification date.</p></div><div className="flex flex-wrap gap-2"><select value={filters.category} onChange={(e)=>setFilters({...filters,category:e.target.value})} className="border border-line bg-cream p-2 text-sm"><option value="">All categories</option>{['PLASTIC','ORGANIC','METAL','OTHER'].map(x=><option key={x}>{x}</option>)}</select><input type="date" value={filters.from_timestamp} onChange={(e)=>setFilters({...filters,from_timestamp:e.target.value})} className="border border-line bg-cream p-2 text-sm"/><input type="date" value={filters.to_timestamp} onChange={(e)=>setFilters({...filters,to_timestamp:e.target.value})} className="border border-line bg-cream p-2 text-sm"/><button onClick={load} className="bg-terracotta px-4 py-2 text-sm font-bold text-paper hover:bg-clay">Apply</button></div></div><div className="mt-4"><WasteFeedTable events={events} showResident/></div></section></div></div>
}
